#include "windows_theme.hpp"
#include <filesystem>
#include <iostream>
int main(){auto root=std::filesystem::temp_directory_path()/L"kr-mycelia-theme-test";std::error_code ec;std::filesystem::remove_all(root,ec);std::filesystem::create_directories(root);SetEnvironmentVariableW(L"LOCALAPPDATA",root.c_str());if(krmemory::scale_for_dpi(100,96)!=100||krmemory::scale_for_dpi(100,144)!=150){std::cerr<<"DPI scaling failed\n";return 1;}auto settings=krmemory::appearance_settings();settings.theme=3;settings.font_sizes[static_cast<int>(krmemory::UiArea::dashboard)]=2;settings.colors[static_cast<int>(krmemory::UiArea::dashboard)]=4;if(!krmemory::save_appearance_settings(settings)){std::cerr<<"theme persistence failed\n";return 1;}auto restored=krmemory::appearance_settings();auto palette=krmemory::current_ui_palette(krmemory::UiArea::dashboard);if(restored.theme!=3||restored.font_sizes[1]!=2||restored.colors[1]!=4||palette.text==RGB(0xfd,0xf4,0xff)||palette.accent!=RGB(0xc0,0x26,0xd3)||palette.background==palette.text||palette.surface==palette.text){std::cerr<<"theme settings or contrast failed\n";return 1;}if(!std::filesystem::is_regular_file(root/L"KRMyceliaNativeMemory"/L"ui-settings.txt")){std::cerr<<"theme settings file missing\n";return 1;}std::filesystem::remove_all(root,ec);std::cout<<"PASS: DPI scaling, six themes, per-area font/color and persistence\n";return 0;}
